  // ---- 1. Decode 2160x1080 Natural Earth 50m Land/Sea Bitmask (O(1) query)
  const ALPH = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-_';
  let landBits = null;
  function ensureLandMask() {
    if (landBits) return landBits;
    const W = RAW.landmask.w, H = RAW.landmask.h, str = RAW.landmask.vlq;
    const total = W * H;
    const bits = new Uint8Array((total + 7) >> 3);
    const rev = new Int8Array(128).fill(-1);
    for (let i = 0; i < ALPH.length; i++) rev[ALPH.charCodeAt(i)] = i;
    let idx = 0, bitVal = 0, px = 0;
    while (idx < str.length && px < total) {
      let run = 0, shift = 0;
      while (idx < str.length) {
        const v = rev[str.charCodeAt(idx++)];
        run |= (v & 31) << shift;
        shift += 5;
        if ((v & 32) === 0) break;
      }
      if (bitVal === 1 && run > 0) {
        const end = Math.min(total, px + run);
        for (let p = px; p < end; p++) {
          bits[p >> 3] |= (1 << (7 - (p & 7)));
        }
      }
      px += run;
      bitVal ^= 1;
    }
    landBits = bits;
    return landBits;
  }

  function isLand(lat, lon) {
    const bits = ensureLandMask();
    const W = RAW.landmask.w, H = RAW.landmask.h;
    const normLon = ((((lon + 180) % 360) + 360) % 360) - 180;
    const x = Math.max(0, Math.min(W - 1, Math.floor((normLon + 180) / 360 * W)));
    const y = Math.max(0, Math.min(H - 1, Math.floor((90 - lat) / 180 * H)));
    const p = y * W + x;
    return ((bits[p >> 3] >> (7 - (p & 7))) & 1) === 1;
  }

  function pathCrossesSea(lat1, lon1, lat2, lon2) {
    const steps = 40;
    let waterRun = 0, maxWaterRun = 0, waterCount = 0;
    for (let i = 1; i < steps; i++) {
      const t = i / steps;
      const lat = lat1 + (lat2 - lat1) * t;
      const lon = lon1 + (lon2 - lon1) * t;
      if (!isLand(lat, lon)) {
        waterRun++;
        waterCount++;
        if (waterRun > maxWaterRun) maxWaterRun = waterRun;
      } else {
        waterRun = 0;
      }
    }
    return maxWaterRun >= 2 || waterCount >= 3;
  }

  // ---- 2. WGS-84 -> Standard Military/AFAD MGRS Converter
  function latLonToMGRS(lat, lon) {
    if (lat < -80 || lat > 84) return 'UPS-POLAR';
    const d2r = Math.PI / 180;
    const normLon = ((((lon + 180) % 360) + 360) % 360) - 180;
    let zone = Math.floor((normLon + 180) / 6) + 1;
    if (lat >= 56 && lat < 64 && normLon >= 3 && normLon < 12) zone = 32;
    const bandLetters = 'CDEFGHJKLMNPQRSTUVWXX';
    const band = bandLetters[Math.max(0, Math.min(20, Math.floor((lat + 80) / 8)))];
    const lon0 = ((zone - 1) * 6 - 180 + 3) * d2r;
    const phi = lat * d2r, lam = normLon * d2r;
    const a = 6378137.0, e2 = 0.00669437999014, ep2 = e2 / (1 - e2);
    const N = a / Math.sqrt(1 - e2 * Math.sin(phi) ** 2);
    const T = Math.tan(phi) ** 2, C = ep2 * Math.cos(phi) ** 2;
    const A = Math.cos(phi) * (lam - lon0);
    const M = a * ((1 - e2 / 4 - 3 * e2 * e2 / 64) * phi - (3 * e2 / 8 + 3 * e2 * e2 / 32) * Math.sin(2 * phi) + (15 * e2 * e2 / 256) * Math.sin(4 * phi));
    const k0 = 0.9996;
    const easting = k0 * N * (A + (1 - T + C) * A ** 3 / 6) + 500000.0;
    let northing = k0 * (M + N * Math.tan(phi) * (A * A / 2 + (5 - T + 9 * C + 4 * C * C) * A ** 4 / 24));
    if (lat < 0) northing += 10000000.0;
    const set = (zone - 1) % 6;
    const colLetters = ['ABCDEFGH', 'JKLMNPQR', 'STUVWXYZ'][set % 3];
    const rowLetters = (set % 2 === 0) ? 'ABCDEFGHJKLMNPQRSTUV' : 'FGHJKLMNPQRSTUVABCDE';
    const e100k = Math.floor(easting / 100000);
    const n100k = Math.floor(northing / 100000) % 20;
    const colCh = colLetters[Math.max(0, Math.min(7, e100k - 1))];
    const rowCh = rowLetters[n100k];
    const e5 = String(Math.floor(easting % 100000)).padStart(5, '0').slice(0, 4);
    const n5 = String(Math.floor(northing % 100000)).padStart(5, '0').slice(0, 4);
    return `${zone}${band}${colCh}${rowCh} ${e5} ${n5}`;
  }

